'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=s=>{try{let u=new URL(s);return u.protocol==='https:'?esc(u.href):'#'}catch{return '#'}};
let products=[],trials=[],news=[],mode='approved',newsMode='all';
const phase=s=>String(s||'未提供').replaceAll('PHASE','Phase ').replaceAll('_',' / '), status=s=>({RECRUITING:'招募中',ACTIVE_NOT_RECRUITING:'進行中・未招募',COMPLETED:'已完成',TERMINATED:'已終止',NOT_YET_RECRUITING:'尚未招募',WITHDRAWN:'已撤回',SUSPENDED:'暫停'}[s]||s||'未提供');
function render(){if(mode==='research'){renderResearch();return;}let q=$('#search').value.toLowerCase(),target=$('#target').value;let list=(mode==='approved'?products:trials).filter(p=>JSON.stringify(p).toLowerCase().includes(q)&&(!target||(p.target||JSON.stringify(p.interventions)).includes(target)));$('#result-count').textContent=`${list.length} 筆結果`;
$('#scope').textContent=mode==='approved'?'首版以美國／歐盟已核准產品為核心，另收錄部分中國產品，非全球完整清單。適應症摘要依卡片所列地區；請查當地仿單。':'研究以「試驗」為單位，可能包含已上市產品的新用途；進入試驗不代表獲准用於該疾病。收錄不是完整管線清單。';
$('#cards').innerHTML=list.length?list.map(p=>mode==='approved'?`<article class="therapy-card"><div class="card-top"><span class="badge approved">已上市・部分地區</span><span class="target">${esc(p.target)} / ${esc(p.cell)}</span></div><h3>${esc(p.name)}</h3><div class="inn">${esc(p.inn)}</div><p>${esc(p.indication)}</p><div class="maker">${esc(p.maker)}</div><div class="card-bottom"><span>查證 ${esc(p.verifiedAt)}</span><button data-product="${esc(p.name)}">查看詳情 ↗</button></div></article>`:`<article class="therapy-card"><div class="card-top"><span class="badge research">研究中用途</span><span class="target">${esc(phase(p.phase))}</span></div><h3 style="font-size:18px">${esc(p.title)}</h3><p>${esc((p.interventions||[]).join(' / '))}</p><div class="inn">${esc((p.conditions||[]).join(' / '))}</div><div class="maker">登錄狀態：${esc(status(p.status))}<br>${esc(p.note||'登錄資料不代表已證實療效或獲得核准。')}</div><div class="card-bottom"><span>來源更新 ${esc(p.updated)}</span><a class="source" href="${safe(p.source)}" target="_blank" rel="noopener">${esc(p.id)} ↗</a></div></article>`).join(''):'<p class="empty">沒有符合條件的資料。請調整搜尋條件。</p>';
}
function renderResearch(){const q=$('#search').value.toLowerCase(),target=$('#target').value;const list=trials.filter(p=>JSON.stringify(p).toLowerCase().includes(q)&&(!target||p.target===target));$('#result-count').textContent=list.length+' 個標靶分類';$('#scope').textContent='依標靶整理研究方向；摘要為編輯整理，不是完整試驗清單。外部資料以來源最新內容為準，研究用途不等於獲准用途。';$('#cards').innerHTML=list.length?list.map(p=>'<article class="therapy-card"><div class="card-top"><span class="badge research">研究方向摘要</span><span class="target">'+esc(p.target)+'</span></div><h3>'+esc(p.target)+'</h3><p><b>'+esc(p.title)+'</b></p><p>'+esc(p.summary)+'</p><div class="card-bottom"><span>摘要核對 '+esc(p.reviewedAt)+'</span><a class="source" href="'+safe(p.url)+'" target="_blank" rel="noopener">閱讀外部來源 ↗</a></div></article>').join(''):'<p class="empty">沒有符合的標靶分類。</p>';}
function syncTargets(){const select=$('#target'),previous=select.value;const targets=[...new Set((mode==='research'?trials:products).map(p=>p.target))].filter(Boolean);select.disabled=false;select.innerHTML='<option value="">全部靶點</option>'+targets.map(t=>'<option value="'+esc(t)+'">'+esc(t)+'</option>').join('');select.value=targets.includes(previous)?previous:'';$('#search').placeholder=mode==='research'?'搜尋標靶、疾病或研究方向…':'搜尋產品、靶點、適應症…';}
function setMode(m){mode=m;['approved','research'].forEach(x=>{let b=$('#'+x+'-tab');b.classList.toggle('active',m===x);b.setAttribute('aria-selected',m===x)});syncTargets();render()}
function renderNews(){let l=news.filter(n=>n.type!=='試驗更新').filter(n=>newsMode==='all'||n.type===newsMode).sort((a,b)=>b.date.localeCompare(a.date));$('#news-list').innerHTML=l.length?l.slice(0,40).map(n=>`<article class="news-item"><div class="news-meta"><span class="badge ${n.review==='已核對'?'approved':'research'}">${esc(n.type)}</span><div>${esc(n.date)}</div></div><div><a href="${safe(n.url)}" target="_blank" rel="noopener"><h3>${esc(n.title)}</h3></a><p>${esc(n.summary||'原文資料，請點閱來源；尚未經人工審閱。')}</p><div class="news-source">${esc(n.source)} · ${esc(n.review||'自動匯入・未審閱')}</div></div><a href="${safe(n.url)}" target="_blank" rel="noopener" aria-label="閱讀來源">↗</a></article>`).join(''):'<p class="empty">此分類目前沒有資料。啟用排程後，符合條件的新資料將自動匯入。</p>'}
$('#approved-tab').onclick=()=>setMode('approved');$('#research-tab').onclick=()=>setMode('research');$('#view-research').onclick=()=>setMode('research');$('#search').oninput=render;$('#target').onchange=render;
$('#cards').onclick=e=>{let b=e.target.closest('[data-product]');if(!b)return;let p=products.find(x=>x.name===b.dataset.product);$('#dialog-content').innerHTML=`<p class="eyebrow">${esc(p.target)} / ${esc(p.cell)} CAR-T</p><h2>${esc(p.name)}</h2><p class="inn">${esc(p.inn)} · ${esc(p.maker)}</p><h3>適應症摘要（${p.primaryRegion==='CN'?'中國':'美國'}）</h3><p>${esc(p.detail)}</p><h3>地區核准狀態</h3><p>核准不代表當地供應或給付；各地年齡、線別及疾病範圍可能不同。</p>${Object.entries(p.regions).map(([k,v])=>`<p><b>${esc(k)}</b>　${esc(v.status)}　<a class="source" target="_blank" rel="noopener" href="${safe(v.source)}">查看當地來源 ↗</a></p>`).join('')}<p class="inn">人工查證 ${esc(p.verifiedAt)}；新來源異動不會自動改寫此紀錄。</p>`;$('#product-dialog').showModal()};$('#close-dialog').onclick=()=>$('#product-dialog').close();$('#product-dialog').onclick=e=>{if(e.target===$('#product-dialog'))$('#product-dialog').close()};
document.querySelectorAll('[data-news]').forEach(b=>b.onclick=()=>{newsMode=b.dataset.news;document.querySelectorAll('[data-news]').forEach(x=>x.classList.toggle('active',x===b));renderNews()});
(async()=>{try{let data=await Promise.all(['products','research-summaries','news','health'].map(async n=>{const r=await fetch('data/'+n+'.json');if(!r.ok)throw Error(n);return r.json()}));[products,trials,news]=data;let health=data[3];$('#product-count').textContent=String(products.length).padStart(2,'0');$('#freshness').textContent=health.lastAttempt?(health.lastSuccess?'已執行自動更新':'部分來源更新失敗'):'排程尚未啟用';$('#update-detail').textContent=health.lastAttempt?`最近嘗試：${health.lastAttempt}；最近完整成功：${health.lastSuccess}。${Object.entries(health.sources||{}).map(([k,v])=>k+'：'+v.status).join(' / ')}。核准資料仍以人工查證日期為準。`:health.mode+'。GitHub Actions 啟用後每日台灣時間約 08:20 抓取，排程可能延遲。';$('#matrix').innerHTML=products.map(p=>`<tr><td>${esc(p.name)}</td>${['US','EU','JP','TW','CN','UK'].map(k=>{let v=p.regions[k];return `<td><a class="badge ${v.status==='待查證'?'unknown':v.status==='附條件核准'?'conditional':'approved'}" href="${safe(v.source)}" target="_blank" rel="noopener" aria-label="${esc(p.name+' '+k+' '+v.status+' 來源')}">${esc(v.status)} ↗</a></td>`}).join('')}</tr>`).join('');syncTargets();render();renderNews()}catch(e){$('#cards').innerHTML='<p class="empty">無法載入資料。請透過網站網址開啟，或稍後重新整理。</p>';$('#freshness').textContent='資料載入失敗';$('#update-detail').textContent='目前無法讀取更新紀錄。'}})();
